TOTAL_STAGES=14

# gradle_ayari_yaz AD DEGER: gradle.properties'teki bir derleme ayarını günceller (gizli olmayan değerler).
gradle_ayari_yaz() {
  local tmp; tmp=$(mktemp)
  sed "s#^$1=.*#$1=$2#" gradle.properties > "$tmp"
  mv "$tmp" gradle.properties
  printf '  %s✓ wrote%s %s → gradle.properties\n' "$GREEN" "$RESET" "$1"
}

