if [[ -f "$HOME/.android/debug.keystore" ]] && command -v keytool >/dev/null 2>&1; then
  note "Debug imzasının SHA-1'i:"
  keytool -list -v -keystore "$HOME/.android/debug.keystore" -alias androiddebugkey -storepass android -keypass android 2>/dev/null | grep 'SHA1:' | sed 's/^/    /'
else
  warn "Debug keystore bulunamadı; Android uygulamasını bir kez derleyince ~/.android/debug.keystore oluşur."
  note "Sonra: keytool -list -v -keystore ~/.android/debug.keystore -alias androiddebugkey -storepass android"
fi
open_url "https://console.cloud.google.com/apis/credentials"
step "'+ Create credentials' → 'OAuth client ID' → Application type: 'Android'."
step "Package name: com.sosyaloyun.app, SHA-1: yukarıdaki değer → Create."
note "Mağaza (release) imzası için aynı şekilde ikinci bir Android istemcisi gerekir; o, mağaza yüklemesiyle birlikte yapılır."
pause "Android istemcisi oluşturulunca Enter'a bas"
note "gradle.properties ve Config.xcconfig değişikliklerini commit'leyip main'e gönder (değerler gizli değil)."
# ──────────────────────────────────────────────────────────────────────────

finish
